UPDATE artist_artwork_batch SET status=CASE WHEN EXISTS(SELECT 1 FROM artist_artwork_item WHERE batch_id=artist_artwork_batch.id AND status IN ('PENDING','PROCESSING')) THEN 'RUNNING' ELSE 'COMPLETED' END,updated_at=?,finished_at=CASE WHEN EXISTS(SELECT 1 FROM artist_artwork_item WHERE batch_id=artist_artwork_batch.id AND status IN ('PENDING','PROCESSING')) THEN NULL ELSE ? END WHERE id=?;
